    // reward this bin heavily to encourage pairing items.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Threshold: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the average 
        // occupancy of existing bins is already very high (mean_residual is low).
        if open_bins_count > 0 && mean_residual > 15.0 {
            score += 20.0; // Penalty for opening new bin too early
        } else {
            score += 45.0; // Strong penalty to force usage of existing space
        }
    } else {
        // 4. Scarcity Logic: If this is the last bin that can fit the item, 
        // prioritize it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Dynamic Time Horizon: As we reach the end of the stream, 
    // prioritize packing tighter to avoid leftovers.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

