pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the minimum possible item size (10)
    // are often useless. We penalize post_residual values in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Heuristic: If this is the last bin that can fit the item, prioritize it to avoid
    // opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // If we are considering opening a new bin (bin_residual == bin_capacity),
    // only do so if the current open bins are highly fragmented or if we have few bins open.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 45.0 + (open_bins_count as f64 * 0.5);

        // If next_item_size is large, opening a new bin is better than cramping it into a tight spot.
        if next_item_size > 70 {
            score -= 15.0;
        }
    }

    // Pressure to consolidate: penalize high open_bins_count to encourage using existing capacity.
    score += (open_bins_count as f64) * 0.2;

    // Favor bins that result in a residual close to the mean_residual of other bins,
    // promoting uniform bin utilization.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits 
    // that leave just enough for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can perfectly or near-perfectly accommodate the next item.
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Penalize creating "dead space" that cannot fit the next item.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 2. Equilibrium Balancing: If post_residual is significantly lower than the mean_residual,
    // we are packing too tightly into one bin, potentially stranding larger items later.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 20.0;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current 
    // packing efficiency is extremely poor or we are forced to.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing one is available.
            score += 85.0;
        } else {
            // Forced to open a new bin.
            score -= 50.0;
        }
    }

    // 4. Progress Awareness: As the stream nears the end, prioritize closing bins
    // by favoring deeper fills (lower post_residual) over lookahead considerations.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}
